"use client"

import * as React from "react"
import { cn } from "@/lib/utils"
import { Slider as SliderPrimitive } from "@base-ui/react/slider"

import "@/styles/slider.styles.css"

function Slider({
  className,
  defaultValue,
  value,
  min = 0,
  max = 100,
  ...props
}: SliderPrimitive.Root.Props) {
  const _values = React.useMemo(() => {
    const currentValue = value ?? defaultValue ?? min
    return Array.isArray(currentValue) ? currentValue : [currentValue]
  }, [value, defaultValue, min])

  return (
    <SliderPrimitive.Root
      className={cn("slider-layout", className)}
      data-slot="slider"
      defaultValue={defaultValue}
      value={value}
      min={min}
      max={max}
      thumbAlignment="edge"
      {...props}
    >
      <SliderPrimitive.Control data-slot="slider-control" className="slider-control-layout">
        <SliderPrimitive.Track data-slot="slider-track" className="slider-track-layout">
          <SliderPrimitive.Indicator data-slot="slider-range" className="slider-range-layout" />
        </SliderPrimitive.Track>
        {Array.from({ length: _values.length }, (_, index) => (
          <SliderPrimitive.Thumb
            data-slot="slider-thumb"
            key={index}
            index={index}
            getAriaLabel={
              props["aria-label"]
                ? () => `${props["aria-label"]}${_values.length > 1 ? ` ${index + 1}` : ""}`
                : undefined
            }
            className="slider-thumb-layout"
          />
        ))}
      </SliderPrimitive.Control>
    </SliderPrimitive.Root>
  )
}

export { Slider }

@layer components {
  .slider-layout {
    width: 100%;
    min-width: 0;
  }
  .slider-layout[data-orientation="vertical"] {
    height: 100%;
    width: auto;
  }
  .slider-control-layout {
    position: relative;
    display: flex;
    align-items: center;
    width: 100%;
    height: calc(24 * var(--component-unit, 0.0625rem));
    touch-action: none;
    user-select: none;
  }
  .slider-control-layout[data-orientation="vertical"] {
    flex-direction: column;
    width: calc(24 * var(--component-unit, 0.0625rem));
    height: 100%;
    min-height: calc(140 * var(--component-unit, 0.0625rem));
  }
  .slider-track-layout {
    position: relative;
    width: 100%;
    height: calc(4 * var(--component-unit, 0.0625rem));
    border-radius: 9999px;
    background: var(--input);
  }
  .slider-track-layout[data-orientation="vertical"] {
    width: calc(4 * var(--component-unit, 0.0625rem));
    height: 100%;
    flex-grow: 1;
  }
  .slider-range-layout {
    height: 100%;
    border-radius: inherit;
    background: var(--primary);
  }
  .slider-range-layout[data-orientation="vertical"] {
    width: 100%;
    height: auto;
  }
  .slider-thumb-layout {
    box-sizing: border-box;
    width: calc(16 * var(--component-unit, 0.0625rem));
    height: calc(16 * var(--component-unit, 0.0625rem));
    border: 1px solid color-mix(in oklab, var(--input) 60%, var(--foreground));
    border-radius: 50%;
    background: var(--card);
    cursor: grab;
  }
  .slider-thumb-layout[data-dragging] {
    background: var(--secondary);
    cursor: grabbing;
  }
  .slider-thumb-layout:has(input:focus-visible) {
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
  .slider-thumb-layout input {
    outline: none;
  }
  .slider-layout[data-invalid] .slider-track-layout {
    background: var(--destructive);
  }
  .slider-thumb-layout[data-invalid] {
    border-color: var(--destructive);
  }
  .slider-layout[data-disabled] .slider-track-layout {
    background: var(--border);
  }
  .slider-layout[data-disabled] .slider-range-layout {
    background: var(--muted-foreground);
  }
  .slider-thumb-layout[data-disabled] {
    border-color: var(--border);
    background: var(--muted);
    cursor: not-allowed;
  }
}
@media (hover: hover) {
  @layer components {
    .slider-thumb-layout:not([data-disabled], [data-dragging]):hover {
      background: var(--muted);
    }
  }
}
@media (pointer: coarse) {
  @layer components {
    .slider-control-layout {
      height: calc(44 * var(--component-unit, 0.0625rem));
    }
    .slider-control-layout[data-orientation="vertical"] {
      width: calc(44 * var(--component-unit, 0.0625rem));
    }
  }
}
@media (forced-colors: active) {
  .slider-thumb-layout:has(input:focus-visible) {
    outline-color: Highlight;
  }
  .slider-range-layout {
    background: Highlight;
    forced-color-adjust: none;
  }
}
